export function buildAddedSelfContent<T extends {
  lifeAlignment: Record<string, unknown>;
  sections: readonly Record<string, unknown>[];
  areas: readonly Record<string, unknown>[];
  currentEmphasis: Record<string, { label: string; description: string }>;
  capacity: Record<string, { label: string; description: string }>;
  direction: Record<string, { label: string; description: string }>;
  constraints: Record<string, string>;
  tradeoffs: Record<string, string>;
  authority: Record<string, string>;
  entanglement: Record<string, string>;
  experiments: Record<string, { label: string; action: string; observe: string }>;
  scene: Record<string, unknown>;
  snapshot: Record<string, { label: string; description: string }>;
  depth: Record<string, string>;
}>(locale: AddedLifeLocale, base: T): T {
  const pack = selfPacks[locale];
  if (!pack) throw new Error(`Missing Life Alignment Self content for ${locale}`);
  const pairRecord = (record: Record<string, { label: string; description: string }>, pairs: readonly Pair[]) => Object.fromEntries(Object.keys(record).map((key, index) => [key, { label: pairs[index][0], description: pairs[index][1] }]));
  const textRecord = (record: Record<string, string>, values: readonly string[]) => Object.fromEntries(Object.keys(record).map((key, index) => [key, values[index]]));
  return {
    ...base,
    lifeAlignment: { ...base.lifeAlignment, title: pack.meta[0], description: pack.meta[1], duration: pack.meta[2], privacy: pack.meta[3], authority: pack.meta[4] },
    sections: base.sections.map((item, index) => ({ ...item, title: pack.sections[index][0], description: pack.sections[index][1] })),
    areas: base.areas.map((item, index) => ({ ...item, title: pack.areas[index][0], description: pack.areas[index][1] })),
    currentEmphasis: pairRecord(base.currentEmphasis, pack.current), capacity: pairRecord(base.capacity, pack.capacity), direction: pairRecord(base.direction, pack.direction),
    constraints: textRecord(base.constraints, pack.constraints), tradeoffs: textRecord(base.tradeoffs, pack.tradeoffs), authority: textRecord(base.authority, pack.authority), entanglement: textRecord(base.entanglement, pack.entanglement),
    experiments: Object.fromEntries(Object.keys(base.experiments).map((key, index) => [key, { label: pack.experiments[index][0], action: pack.experiments[index][1], observe: pack.experiments[index][2] }])),
    scene: { ...base.scene, eyebrow: pack.scene[0], title: pack.scene[1], description: pack.scene[2], alt: pack.scene[3] },
    snapshot: pairRecord(base.snapshot, pack.snapshot), depth: { evidenceLabel: pack.depth[0], pathsBoundary: pack.depth[1], toolsBoundary: pack.depth[2] },
  } as unknown as T;
}

