export function buildAddedPartnerContent<T extends {
  module: Record<string, unknown>; scene: Record<string, unknown>; sections: readonly Record<string, unknown>[]; dimensions: readonly Record<string, unknown>[];
  experience: Record<string, string>; direction: Record<string, string>; importance: Record<string, string>; certainty: Record<string, string>; expectation: Record<string, string>; difference: Record<string, string>; constraint: Record<string, string>; findingLabels: Record<string, string>;
  pathCopy: Record<string, { title: string; approach: string; tradeoffs: string; reversibility: string; whatCouldBeLearned: string }>; disclaimer: string;
}>(locale: AddedLifeLocale, base: T): T {
  const pack = partnerPacks[locale];
  const textRecord = (record: Record<string, string>, values: readonly string[]) => Object.fromEntries(Object.keys(record).map((key, index) => [key, values[index]]));
  return { ...base,
    module: { ...base.module, title: pack.meta[0], description: pack.meta[1], duration: pack.meta[2], privacy: pack.meta[3] },
    scene: { ...base.scene, eyebrow: pack.scene[0], title: pack.scene[1], description: pack.scene[2], alt: pack.scene[3] },
    sections: base.sections.map((item, index) => ({ ...item, title: pack.sections[index] })),
    dimensions: base.dimensions.map((item, index) => ({ ...item, title: pack.dimensions[index][0], description: pack.dimensions[index][1], examples: pack.dimensions[index].slice(2) })),
    experience: textRecord(base.experience, pack.experience), direction: textRecord(base.direction, pack.direction), importance: textRecord(base.importance, pack.importance), certainty: textRecord(base.certainty, pack.certainty), expectation: textRecord(base.expectation, pack.expectation), difference: textRecord(base.difference, pack.difference), constraint: textRecord(base.constraint, pack.constraint), findingLabels: textRecord(base.findingLabels, pack.findings),
    pathCopy: Object.fromEntries(Object.keys(base.pathCopy).map((key, index) => [key, { title: pack.pathTitles[index], approach: pack.pathCommon[0], tradeoffs: pack.pathCommon[1], reversibility: pack.pathCommon[2], whatCouldBeLearned: pack.pathCommon[3] }])), disclaimer: pack.disclaimer,
  } as unknown as T;
}

